// This is the same server-side request contract used by the approved local
// diagnostic. It is deliberately explicit: authentication headers are not
// inferred from captured traffic or generated by the client.
function createBykeaRequestContract(config) {
  return {
    path: config.fareEndpoint,
    nearbyPath: config.nearbyEndpoint,
    method: "GET",
    buildHeaders({ appUserToken, appUserId }) {
      return {
        "X-App-User-Id": appUserId,
        "X-App-User-Token": appUserToken,
        "X-App-User-Type": config.appUserType,
        "X-App-Language": config.appLanguage,
        "X-App-Version": config.appVersion,
        "X-Loc-Latitude": config.headerLatitude,
        "X-Loc-Longitude": config.headerLongitude,
        "X-Loc-Altitude": config.headerAltitude,
        "X-User-Agent": config.userAgent,
        "User-Agent": config.userAgent,
      };
    },
    buildNearbyHeaders({ appUserToken, appUserId, latitude, longitude }) {
      return {
        ...this.buildHeaders({ appUserToken, appUserId }),
        "X-Loc-Latitude": String(latitude),
        "X-Loc-Longitude": String(longitude),
      };
    },
    parseResponse(body) {
      return body;
    },
  };
}

module.exports = { createBykeaRequestContract };
